using System.ComponentModel.DataAnnotations;

namespace TripLog.Models
{
    /// A trip saved to the database. Everything lives in a single Trips table;
    /// Accommodation and ThingsToDo are owned types stored as columns on it.
     
    public class Trip
    {
        // Primary key, generated by the database
        public int TripId { get; set; }

        // Required: where the trip is going
        [Required(ErrorMessage = "Please enter a destination.")]
        public string Destination { get; set; } = "";

        // Required: first day of the trip
        [Required(ErrorMessage = "Please enter a start date."), DataType(DataType.Date)]
        public DateTime StartDate { get; set; }

        // Required: last day of the trip
        [Required(ErrorMessage = "Please enter an end date."), DataType(DataType.Date)]
        public DateTime EndDate { get; set; }

        // Optional: only filled in if the user entered accommodation details
        public Accommodation? Accommodation { get; set; }

        // Optional: only filled in if the user entered activities
        public ThingsToDo? ThingsToDo { get; set; }
    }
    
    public class Accommodation
    {
        // Optional: All Accommadation Strings are Optional 
        public string? Name { get; set; }
        public string? Phone { get; set; }
        public string? Email { get; set; }
    }


    public class ThingsToDo
    {
        // Optional: All Activites are Optional 

        public string? Activity1 { get; set; }
        public string? Activity2 { get; set; }
        public string? Activity3 { get; set; }
    }
}